"""Small polygon font shared with the browser coordinate-label design."""
import math

GLYPHS = {'0': ['01110', '10001', '10011', '10101', '11001', '10001', '01110'], '1': ['00100', '01100', '00100', '00100', '00100', '00100', '01110'], '2': ['01110', '10001', '00001', '00010', '00100', '01000', '11111'], '3': ['11110', '00001', '00001', '01110', '00001', '00001', '11110'], '4': ['00010', '00110', '01010', '10010', '11111', '00010', '00010'], '5': ['11111', '10000', '10000', '11110', '00001', '00001', '11110'], '6': ['01110', '10000', '10000', '11110', '10001', '10001', '01110'], '7': ['11111', '00001', '00010', '00100', '01000', '01000', '01000'], '8': ['01110', '10001', '10001', '01110', '10001', '10001', '01110'], '9': ['01110', '10001', '10001', '01111', '00001', '00001', '01110'], 'X': ['10001', '10001', '01010', '00100', '01010', '10001', '10001'], 'Y': ['10001', '10001', '01010', '00100', '00100', '00100', '00100'], '=': ['00000', '00000', '11111', '00000', '11111', '00000', '00000'], '-': ['00000', '00000', '00000', '11111', '00000', '00000', '00000'], '.': ['00000', '00000', '00000', '00000', '00000', '00110', '00110'], 'u': ['00000', '00000', '10001', '10001', '10001', '10011', '01101'], 'm': ['00000', '00000', '11010', '10101', '10101', '10101', '10101'], ' ': ['00000', '00000', '00000', '00000', '00000', '00000', '00000'], 'A': ['01110', '10001', '10001', '11111', '10001', '10001', '10001'], 'B': ['11110', '10001', '10001', '11110', '10001', '10001', '11110'], 'C': ['01111', '10000', '10000', '10000', '10000', '10000', '01111'], 'D': ['11110', '10001', '10001', '10001', '10001', '10001', '11110'], 'E': ['11111', '10000', '10000', '11110', '10000', '10000', '11111'], 'F': ['11111', '10000', '10000', '11110', '10000', '10000', '10000'], 'G': ['01111', '10000', '10000', '10111', '10001', '10001', '01111'], 'H': ['10001', '10001', '10001', '11111', '10001', '10001', '10001'], 'I': ['01110', '00100', '00100', '00100', '00100', '00100', '01110'], 'J': ['00001', '00001', '00001', '00001', '10001', '10001', '01110'], 'K': ['10001', '10010', '10100', '11000', '10100', '10010', '10001'], 'L': ['10000', '10000', '10000', '10000', '10000', '10000', '11111'], 'M': ['10001', '11011', '10101', '10101', '10001', '10001', '10001'], 'N': ['10001', '11001', '10101', '10011', '10001', '10001', '10001'], 'O': ['01110', '10001', '10001', '10001', '10001', '10001', '01110'], 'P': ['11110', '10001', '10001', '11110', '10000', '10000', '10000'], 'Q': ['01110', '10001', '10001', '10001', '10101', '10010', '01101'], 'R': ['11110', '10001', '10001', '11110', '10100', '10010', '10001'], 'S': ['01111', '10000', '10000', '01110', '00001', '00001', '11110'], 'T': ['11111', '00100', '00100', '00100', '00100', '00100', '00100'], 'U': ['10001', '10001', '10001', '10001', '10001', '10001', '01110'], 'V': ['10001', '10001', '10001', '10001', '10001', '01010', '00100'], 'W': ['10001', '10001', '10001', '10101', '10101', '11011', '10001'], 'Z': ['11111', '00001', '00010', '00100', '01000', '10000', '11111'], '_': ['00000', '00000', '00000', '00000', '00000', '00000', '11111'], ':': ['00000', '00100', '00100', '00000', '00100', '00100', '00000'], '/': ['00001', '00010', '00010', '00100', '01000', '01000', '10000'], '+': ['00000', '00100', '00100', '11111', '00100', '00100', '00000'], '(': ['00010', '00100', '01000', '01000', '01000', '00100', '00010'], ')': ['01000', '00100', '00010', '00010', '00010', '00100', '01000'], ',': ['00000', '00000', '00000', '00000', '00100', '00100', '01000']}

def format_coordinate(value):
    rounded = math.floor(value * 1000 + 0.5) / 1000
    return format(rounded, ".3f").rstrip("0").rstrip(".") if rounded else "0"

def coordinate_rectangles(x, y, height):
    size = height / 7
    rectangles = []
    lines = ("X=" + format_coordinate(x) + " um", "Y=" + format_coordinate(y) + " um")
    for line, text in enumerate(lines):
        for i, char in enumerate(text):
            for row, bitmap in enumerate(GLYPHS[char]):
                column = 0
                while column < 5:
                    if bitmap[column] != "1":
                        column += 1
                        continue
                    start = column
                    while column < 5 and bitmap[column] == "1":
                        column += 1
                    rectangles.append((i * 6 * size + start * size,
                                       -line * 9 * size + (6 - row) * size,
                                       i * 6 * size + column * size,
                                       -line * 9 * size + (7 - row) * size))
    return rectangles

def text_rectangles(text, height):
    size = height / 7
    out = []
    for line, value in enumerate(text.split("\n")):
        for i, char in enumerate(value.upper()):
            if char not in GLYPHS:
                raise ValueError("Unsupported label character: " + char)
            for row, bitmap in enumerate(GLYPHS[char]):
                col = 0
                while col < 5:
                    if bitmap[col] != "1":
                        col += 1
                        continue
                    start = col
                    while col < 5 and bitmap[col] == "1":
                        col += 1
                    out.append((i*6*size+start*size, -line*9*size+(6-row)*size,
                                i*6*size+col*size, -line*9*size+(7-row)*size))
    return out
